/* Suy ra phan / baiTap của cả bài từ các phần, và cấu trúc phần cho chiaPhan. */
export const BAI_A2 = BAI.map((b) => {
  const phan = [], baiTap = [], cauTruc = [];
  for (const p of b.phanCon) {
    const k0 = phan.length, c0 = baiTap.length;
    phan.push(...p.khoi); baiTap.push(...p.cau);
    cauTruc.push({ ten: p.ten, giai: p.giai, khoi: p.khoi.map((_, i) => k0 + i), cau: p.cau.map((_, i) => c0 + i) });
  }
  return { ma: b.ma, cap: "A2", ten: b.ten, tenFr: b.tenFr, tomTat: b.tomTat, tuKhoa: b.tuKhoa, phan, baiTap, cauTruc };
});
